module compute_F(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] x,\n    input [3:0] y,\n    output reg [31:0] result,\n    output reg done\n);\n    \n    localparam [31:0] MOD = 32'd1000000007;\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state, next_state;\n    reg [3:0] i, j;\n    reg [31:0] dp [0:8][0:8];\n    reg [3:0] m, n; // For reset loops\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            i <= 4'd0;\n            j <= 4'd0;\n            \n            // Initialize dp array\n            for (m = 4'd0; m <= 4'd8; m = m + 4'd1) begin\n                for (n = 4'd0; n <= 4'd8; n = n + 4'd1) begin\n                    dp[m][n] <= 32'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 32'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    // Compute current dp[i][j]\n                    if (i == 4'd0 && j == 4'd0) begin\n                        dp[i][j] <= 32'd0;\n                    end else if ((i == 4'd0 && j == 4'd1) || (i == 4'd1 && j == 4'd0)) begin\n                        dp[i][j] <= 32'd1;\n                    end else if (i == 4'd0) begin\n                        dp[i][j] <= (dp[i][j-1] + dp[i][j-2]) % MOD;\n                    end else if (j == 4'd0) begin\n                        dp[i][j] <= (dp[i-1][j] + dp[i-2][j]) % MOD;\n                    end else begin\n                        dp[i][j] <= (dp[i-1][j] + dp[i][j-1]) % MOD;\n                    end\n                    \n                    // Update counters\n                    if (j == y) begin\n                        if (i == x) begin\n                            state <= DONE_ST;\n                            result <= dp[x][y];\n                        end else begin\n                            i <= i + 4'd1;\n                            j <= 4'd0;\n                        end\n                    end else begin\n                        j <= j + 4'd1;\n                    end\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule